#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const char *input = "";
    if (argc > 1) {
        input = argv[1];
    }
    size_t len = strlen(input);
    if (len > 1024) {
        puts("TOO_LONG");
        return 0;
    }
    char norm[1025];
    size_t n = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';
    int ispal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            ispal = 0;
            break;
        }
    }
    puts(ispal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
